  '[{"id":"q1","question":"¿Cuántos continentes hay en la Tierra?","options":[{"id":"a","text":"Cinco","is_correct":false},{"id":"b","text":"Seis","is_correct":false},{"id":"c","text":"Siete","is_correct":true},{"id":"d","text":"Ocho","is_correct":false}],"explanation":"El conteo habitual es siete: África, Antártida, Asia, Europa, América del Norte, Oceanía y América del Sur."},{"id":"q2","question":"¿Qué planeta es conocido como el Planeta Rojo?","options":[{"id":"a","text":"Venus","is_correct":false},{"id":"b","text":"Marte","is_correct":true},{"id":"c","text":"Júpiter","is_correct":false},{"id":"d","text":"Mercurio","is_correct":false}],"explanation":"El polvo rico en óxido de hierro de su superficie le da a Marte su color rojizo."},{"id":"q3","question":"¿Cuál es el mamífero más grande del mundo?","options":[{"id":"a","text":"El elefante africano","is_correct":false},{"id":"b","text":"La ballena azul","is_correct":true},{"id":"c","text":"La jirafa","is_correct":false},{"id":"d","text":"La orca","is_correct":false}],"explanation":"Una ballena azul puede medir 30 metros y superar las 150 toneladas."},{"id":"q4","question":"¿Qué gas compone la mayor parte de la atmósfera terrestre?","options":[{"id":"a","text":"Oxígeno","is_correct":false},{"id":"b","text":"Dióxido de carbono","is_correct":false},{"id":"c","text":"Nitrógeno","is_correct":true},{"id":"d","text":"Hidrógeno","is_correct":false}],"explanation":"Cerca del 78 % del aire es nitrógeno; el oxígeno ronda el 21 %."},{"id":"q5","question":"¿Cuál es el símbolo químico del oro?","options":[{"id":"a","text":"Ag","is_correct":false},{"id":"b","text":"Au","is_correct":true},{"id":"c","text":"Gd","is_correct":false},{"id":"d","text":"Go","is_correct":false}],"explanation":"Au viene de aurum, la palabra latina para el oro."},{"id":"q6","question":"¿Qué idioma tiene más hablantes nativos en el mundo?","options":[{"id":"a","text":"El inglés","is_correct":false},{"id":"b","text":"El español","is_correct":false},{"id":"c","text":"El chino mandarín","is_correct":true},{"id":"d","text":"El hindi","is_correct":false}],"explanation":"El mandarín tiene cerca de mil millones de hablantes nativos, más que cualquier otro idioma."},{"id":"q7","question":"¿Cuántos días tiene un año bisiesto?","options":[{"id":"a","text":"364","is_correct":false},{"id":"b","text":"365","is_correct":false},{"id":"c","text":"366","is_correct":true},{"id":"d","text":"367","is_correct":false}],"explanation":"El año bisiesto añade el 29 de febrero para mantener el calendario alineado con la órbita terrestre."},{"id":"q8","question":"¿En qué país se originaron los Juegos Olímpicos?","options":[{"id":"a","text":"Italia","is_correct":false},{"id":"b","text":"Grecia","is_correct":true},{"id":"c","text":"Egipto","is_correct":false},{"id":"d","text":"Francia","is_correct":false}],"explanation":"Los juegos antiguos se celebraban en Olimpia desde el 776 a. C."}]'::jsonb,
