xt":"50","is_correct":false}],"explanation":"Thirteen stripes honour the original colonies."},{"id":"q7","question":"Which country''s flag features a green cedar tree?","options":[{"id":"a","text":"Lebanon","is_correct":true},{"id":"b","text":"Cyprus","is_correct":false},{"id":"c","text":"Sri Lanka","is_correct":false},{"id":"d","text":"Pakistan","is_correct":false}],"explanation":"The cedar is Lebanon''s national emblem, prized since antiquity."},{"id":"q8","question":"Which country''s flag shows an eagle eating a snake on a cactus?","options":[{"id":"a","text":"Guatemala","is_correct":false},{"id":"b","text":"Ecuador","is_correct":false},{"id":"c","text":"Mexico","is_correct":true},{"id":"d","text":"Peru","is_correct":false}],"explanation":"The image recalls the Aztec sign that marked the founding of Tenochtitlan."}]'::jsonb,
  null,
