ext":"15","is_correct":false},{"id":"d","text":"50","is_correct":false}],"explanation":"Las trece franjas rinden homenaje a las colonias originales."},{"id":"q7","question":"¿Qué país lleva un cedro verde en su bandera?","options":[{"id":"a","text":"Líbano","is_correct":true},{"id":"b","text":"Chipre","is_correct":false},{"id":"c","text":"Sri Lanka","is_correct":false},{"id":"d","text":"Pakistán","is_correct":false}],"explanation":"El cedro es el emblema nacional del Líbano, apreciado desde la antigüedad."},{"id":"q8","question":"¿Qué país muestra en su bandera un águila devorando una serpiente sobre un nopal?","options":[{"id":"a","text":"Guatemala","is_correct":false},{"id":"b","text":"Ecuador","is_correct":false},{"id":"c","text":"México","is_correct":true},{"id":"d","text":"Perú","is_correct":false}],"explanation":"La imagen evoca la señal azteca que marcó la fundación de Tenochtitlan."}]'::jsonb,
