"},{"id":"q6","question":"''To infinity and beyond!'' is the catchphrase of which animated film?","options":[{"id":"a","text":"Shrek","is_correct":false},{"id":"b","text":"Toy Story","is_correct":true},{"id":"c","text":"Finding Nemo","is_correct":false},{"id":"d","text":"The Incredibles","is_correct":false}],"explanation":"Buzz Lightyear''s motto in Pixar''s 1995 debut feature."},{"id":"q7","question":"''I''m the king of the world!'' was shouted from the bow of which film''s ship?","options":[{"id":"a","text":"Titanic","is_correct":true},{"id":"b","text":"Avatar","is_correct":false},{"id":"c","text":"Pearl Harbor","is_correct":false},{"id":"d","text":"Poseidon","is_correct":false}],"explanation":"Jack Dawson yells it in James Cameron''s 1997 film."},{"id":"q8","question":"''Life is like a box of chocolates'' is the homespun wisdom of which film?","options":[{"id":"a","text":"Rain Man","is_correct":false},{"id":"b","text":"Cast Away","is_correct":false},{"id":"c","text":"The Terminal","is_correct":false},{"id":"d","text":"Forrest Gump","is_correct":true}],"explanation":"Forrest repeats his mother''s saying throughout the 1994 film."}]'::jsonb,
