  'medium',
  'es',
  (select id from public.categories where slug = 'literature'),
  '[{"id":"q1","question":"¿Quién es el rey de los dioses del monte Olimpo?","options":[{"id":"a","text":"Zeus","is_correct":true},{"id":"b","text":"Poseidón","is_correct":false},{"id":"c","text":"Hades","is_correct":false},{"id":"d","text":"Apolo","is_correct":false}],"explanation":"Zeus gobierna desde el Olimpo y empuña el rayo."},{"id":"q2","question":"¿Qué dios griego gobierna el mar?","options":[{"id":"a","text":"Ares","is_correct":false},{"id":"b","text":"Poseidón","is_correct":true},{"id":"c","text":"Hefesto","is_correct":false},{"id":"d","text":"Hermes","is_correct":false}],"explanation":"Poseidón lleva un tridente y domina los terremotos y los océanos."},{"id":"q3","question":"¿Qué titán robó el fuego a los dioses para entregarlo a la humanidad?","options":[{"id":"a","text":"Prometeo","is_correct":true},{"id":"b","text":"Epimeteo","is_correct":false},{"id":"c","text":"Atlas","is_correct":false},{"id":"d","text":"Ícaro","is_correct":false}],"explanation":"Su castigo fue ser encadenado a una roca mientras un águila le devoraba el hígado cada día."},{"id":"q4","question":"¿Qué héroe decapitó a Medusa?","options":[{"id":"a","text":"Hércules","is_correct":false},{"id":"b","text":"Perseo","is_correct":true},{"id":"c","text":"Teseo","is_correct":false},{"id":"d","text":"Jasón","is_correct":false}],"explanation":"Perseo usó un escudo pulido como espejo para esquivar su mirada petrificante."},{"id":"q5","question":"¿Cómo se llama el caballo alado de la mitología griega?","options":[{"id":"a","text":"Pegaso","is_correct":true},{"id":"b","text":"Quirón","is_correct":false},{"id":"c","text":"Cerbero","is_correct":false},{"id":"d","text":"Argos","is_correct":false}],"explanation":"Pegaso surgió del cuerpo de Medusa cuando Perseo la decapitó."},{"id":"q6","question":"¿Qué diosa nació armada de la cabeza de Zeus?","options":[{"id":"a","text":"Atenea","is_correct":true},{"id":"b","text":"Afrodita","is_correct":false},{"id":"c","text":"Artemisa","is_correct":false},{"id":"d","text":"Hera","is_correct":false}],"explanation":"Atenea surgió con armadura y se convirtió en diosa de la sabiduría y la estrategia."},{"id":"q7","question":"¿Quién voló demasiado cerca del sol con alas de plumas y cera?","options":[{"id":"a","text":"Ícaro","is_correct":true},{"id":"b","text":"Dédalo","is_correct":false},{"id":"c","text":"Orfeo","is_correct":false},{"id":"d","text":"Belerofonte","is_correct":false}],"explanation":"Ícaro ignoró la advertencia de su padre Dédalo y cayó al mar."},{"id":"q8","question":"¿Qué criatura, mitad hombre y mitad toro, vivía en el Laberinto de Creta?","options":[{"id":"a","text":"Centauro","is_correct":false},{"id":"b","text":"Minotauro","is_correct":true},{"id":"c","text":"Cíclope","is_correct":false},{"id":"d","text":"Sátiro","is_correct":false}],"explanation":"El Minotauro fue derrotado por el héroe ateniense Teseo."}]'::jsonb,
