insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-inventions-trivia',
  'Inventions Trivia: 8 Discoveries That Changed the World',
  'Eight questions on the inventors and discoveries that reshaped daily life, from the printing press to the World Wide Web.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'technology'),
  '[{"id":"q1","question":"Who is credited with patenting the telephone in 1876?","options":[{"id":"a","text":"Alexander Graham Bell","is_correct":true},{"id":"b","text":"Thomas Edison","is_correct":false},{"id":"c","text":"Nikola Tesla","is_correct":false},{"id":"d","text":"Samuel Morse","is_correct":false}],"explanation":"Bell registered the patent in 1876 and made the first intelligible call."},{"id":"q2","question":"Who invented the World Wide Web while working at CERN?","options":[{"id":"a","text":"Tim Berners-Lee","is_correct":true},{"id":"b","text":"Bill Gates","is_correct":false},{"id":"c","text":"Steve Jobs","is_correct":false},{"id":"d","text":"Vint Cerf","is_correct":false}],"explanation":"Berners-Lee proposed it in 1989; Vint Cerf co-designed the internet''s TCP/IP instead."},{"id":"q3","question":"Who introduced the movable-type printing press to Europe around 1440?","options":[{"id":"a","text":"Johannes Gutenberg","is_correct":true},{"id":"b","text":"Leonardo da Vinci","is_correct":false},{"id":"c","text":"Isaac Newton","is_correct":false},{"id":"d","text":"James Watt","is_correct":false}],"explanation":"Gutenberg''s press made mass-produced books possible; the Gutenberg Bible was its landmark product."},{"id":"q4","question":"Which brothers made the first controlled, powered aeroplane flight in 1903?","options":[{"id":"a","text":"The Wright brothers","is_correct":true},{"id":"b","text":"The Montgolfier brothers","is_correct":false},{"id":"c","text":"Santos-Dumont","is_correct":false},{"id":"d","text":"Charles Lindbergh","is_correct":false}],"explanation":"Orville and Wilbur Wright flew the Flyer at Kitty Hawk on 17 December 1903."},{"id":"q5","question":"What did Wilhelm Röntgen accidentally discover in 1895?","options":[{"id":"a","text":"Penicillin","is_correct":false},{"id":"b","text":"X-rays","is_correct":true},{"id":"c","text":"Radium","is_correct":false},{"id":"d","text":"The electron","is_correct":false}],"explanation":"Röntgen''s mysterious rays earned him the first Nobel Prize in Physics."},{"id":"q6","question":"Who discovered penicillin in 1928?","options":[{"id":"a","text":"Alexander Fleming","is_correct":true},{"id":"b","text":"Louis Pasteur","is_correct":false},{"id":"c","text":"Marie Curie","is_correct":false},{"id":"d","text":"Robert Koch","is_correct":false}],"explanation":"Fleming noticed mould killing bacteria in a petri dish at St Mary''s Hospital, London."},{"id":"q7","question":"Nikola Tesla is best known for championing which electrical system?","options":[{"id":"a","text":"Direct current","is_correct":false},{"id":"b","text":"Alternating current","is_correct":true},{"id":"c","text":"The light bulb","is_correct":false},{"id":"d","text":"Radio broadcasting","is_correct":false}],"explanation":"Tesla''s AC system beat Edison''s DC in the ''war of the currents''."},{"id":"q8","question":"Who designed the Analytical Engine and is called the ''father of the computer''?","options":[{"id":"a","text":"Charles Babbage","is_correct":true},{"id":"b","text":"Alan Turing","is_correct":false},{"id":"c","text":"Ada Lovelace","is_correct":false},{"id":"d","text":"John von Neumann","is_correct":false}],"explanation":"Babbage designed it in the 1830s; Ada Lovelace wrote the first algorithm for it."}]'::jsonb,
  null,
  array['inventions', 'technology', 'trivia', 'inventors']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
